using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.OData.Query;
using Microsoft.AspNetCore.OData.Routing.Controllers;
using Microsoft.OData.Edm;
using Microsoft.OData.ModelBuilder;
using Prescription.Api.LoggedProfessional;
using Prescription.Application.Prescriptions;

namespace Prescription.Api.Controllers;

/// <summary>
/// Prescriptions of the logged professional with OData ($filter, $orderby, $select, $top, $skip, $count).
/// The query is executed in MySQL (single SQL generated by EF Core).
/// </summary>
[Route("odata")]
[RequireProfessional]
public sealed class PrescriptionsODataController : ODataController
{
    public const string RoutePrefix = "odata";
    public const int MaxTop = 100;

    [HttpGet("Prescriptions")]
    // EnsureStableOrdering = false: keeps the default order (most recent first, tie by id) when paging with
    // $top/$skip; otherwise OData replaces it with "order by Id" (found in the API tests).
    [EnableQuery(MaxTop = MaxTop, EnsureStableOrdering = false)]
    [ProducesResponseType<IEnumerable<PrescriptionListItemDto>>(StatusCodes.Status200OK)]
    public IQueryable<PrescriptionListItemDto> Get([FromServices] ListPrescriptions useCase) =>
        useCase.Execute(RequireProfessionalFilter.GetProfessionalId(HttpContext));

    /// <summary>OData model: entity set "Prescriptions" of the list rows.</summary>
    public static IEdmModel BuildModel()
    {
        var builder = new ODataConventionModelBuilder();
        builder.EntitySet<PrescriptionListItemDto>("Prescriptions");
        return builder.GetEdmModel();
    }
}
